import{_ as r,o as t,c as n,O as s}from"./chunks/framework.2c2d5a61.js";const h=JSON.parse('{"title":"工具 & 运维","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/10-工具运维.md","filePath":"interview/后端/Java/10-工具运维.md","lastUpdated":1789026500000}'),g={name:"interview/后端/Java/10-工具运维.md"};function e(a,o,d,l,i,c){return t(),n("div",null,o[0]||(o[0]=[s('<h1 id="工具-运维" tabindex="-1">工具 &amp; 运维 <a class="header-anchor" href="#工具-运维" aria-label="Permalink to &quot;工具 &amp; 运维&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><blockquote><p><strong>本篇策略</strong>：这一章是「实战感」最强的一章。<strong>线上排查流程、Linux 命令、越权防护</strong>我都有真实经历，要重点讲；删库恢复属于场景题，讲思路就行。</p></blockquote><hr><h2 id="_1-git-常用命令、merge-与-rebase-区别-★★☆" tabindex="-1">1. Git 常用命令、merge 与 rebase 区别 ★★☆ <a class="header-anchor" href="#_1-git-常用命令、merge-与-rebase-区别-★★☆" aria-label="Permalink to &quot;1. Git 常用命令、merge 与 rebase 区别 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 常用命令不用背，写代码天天用。 核心区别：</p><ul><li><strong>merge</strong>：<strong>保留分支历史</strong>，多一个合并提交，历史是分叉的 —— 安全。</li><li><strong>rebase</strong>：把自己的提交挪到目标分支后面，历史是<strong>一条直线</strong>，但会<strong>改写提交记录</strong> —— 所以<strong>只能用在没推送出去的本地分支</strong>。</li><li><strong>reset vs revert</strong>：reset 移动 HEAD <strong>会丢提交</strong>；revert 生成一个<strong>反向提交</strong>，历史保留，更安全。</li></ul><p><strong>我的项目关联</strong> 日常使用层面。<strong>真实习惯</strong>：个人 feature 分支我会先 <strong>rebase 拉平历史</strong>再提 MR，公共分支（main / develop）<strong>绝对不 rebase</strong>，只用 merge，避免把别人的<strong>提交历史搞乱</strong>。</p><p><strong>面试答题话术</strong> 「merge 保留历史、安全；rebase <strong>历史干净</strong>但是<strong>改写提交</strong>，只能用在<strong>没推送的个人分支</strong>。我们团队规范就是：个人分支 rebase 保持整洁，<strong>公共分支只 merge</strong>。回退线上问题用 revert，不用 reset，因为 reset <strong>会丢历史</strong>。」</p><hr><h2 id="_2-maven-依赖冲突-★★☆" tabindex="-1">2. Maven 依赖冲突 ★★☆ <a class="header-anchor" href="#_2-maven-依赖冲突-★★☆" aria-label="Permalink to &quot;2. Maven 依赖冲突 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> A 依赖 B(1.0)、C 依赖 B(2.0)，同时引进来就<strong>冲突</strong>。 Maven 默认两个原则：<strong>最短路径优先</strong>、<strong>最先声明优先</strong>。 解决手段：<code>&lt;exclusion&gt;</code> 排除、<code>dependencyManagement</code> <strong>统一锁版本</strong>，用 <code>mvn dependency:tree</code> 看<strong>依赖树定位</strong>。</p><p><strong>我的项目关联</strong><strong>真实遇到过</strong>：多模块项目里不同模块引了<strong>不同版本的公共库</strong>，出现 <code>NoSuchMethodError</code> 这种运行时报错（<strong>编译能过，运行才炸</strong>），就是用 <code>dependency:tree</code> 定位后统一版本解决的。这类问题在 <strong>Spring Boot 多模块项目</strong>里挺常见。</p><p><strong>面试答题话术</strong> 「Maven 冲突默认按<strong>最短路径和最先声明</strong>来选版本。定位靠 <code>dependency:tree</code>。我们真遇到过——多模块引了<strong>不同版本</strong>，编译能过但运行时 <code>NoSuchMethodError</code>，就是<strong>依赖冲突</strong>。解决方式是 <code>dependencyManagement</code> 统一版本，或者 exclusion 排除。」</p><hr><h2 id="_3-docker-基础概念-★★☆" tabindex="-1">3. Docker 基础概念 ★★☆ <a class="header-anchor" href="#_3-docker-基础概念-★★☆" aria-label="Permalink to &quot;3. Docker 基础概念 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 镜像（<strong>只读模板</strong>、<strong>分层构建</strong>）、容器（镜像的运行实例、共享宿主机内核）、Dockerfile（构建脚本）、仓库（Harbor / Docker Hub）。 和虚拟机的区别：虚拟机虚拟一整套 OS（重、隔离彻底），容器<strong>共享内核</strong>（轻、<strong>秒级启动</strong>、隔离弱一些）。 分层的好处：<strong>公共层可复用</strong>，构建和传输都省。</p><p><strong>我的项目关联</strong><strong>真实环境</strong>：我们后端服务都是<strong>容器化部署</strong>的，镜像推到<strong>私有仓库</strong>，K8s 拉起。<strong>真实踩过的坑</strong>跟 JVM 有关 —— 容器有内存限制，如果 JVM 不显式设堆大小，可能被 <strong>OOM Killer 干掉</strong>（进程 <strong>exit 137</strong>），这个在 02 笔记里详细讲过，是<strong>真实踩过的</strong>。</p><p><strong>面试答题话术</strong> 「镜像是模板、容器是运行实例，<strong>共享宿主机内核</strong>所以比虚拟机轻。我们服务都是容器化部署的。这里有个真实的坑：<strong>容器内存限制和 JVM 堆要配套设置</strong>，不设堆大小容易触发 <strong>OOM Killer 把进程杀掉</strong>，我们是踩过的。」</p><hr><h2 id="_4-linux-常用命令-进程、日志、端口、内存-cpu-★★★-【简历亮点-高频追问】" tabindex="-1">4. Linux 常用命令：进程、日志、端口、内存 CPU ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_4-linux-常用命令-进程、日志、端口、内存-cpu-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;4. Linux 常用命令：进程、日志、端口、内存 CPU ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 按场景记，别背清单：</p><ul><li>进程 / CPU：<code>top</code>、<code>ps -ef | grep</code>、<code>kill -9</code>、<code>nohup ... &amp;</code></li><li>日志：<code>tail -f</code>、<code>grep</code>、<code>less</code></li><li>端口：<code>netstat -tlnp</code>、<code>ss -tlnp</code>、<code>lsof -i:8080</code></li><li>资源：<code>free -h</code>（内存）、<code>df -h</code>（磁盘）、<code>du -sh *</code>（目录大小）</li><li>文件：<code>find</code>、<code>chmod</code>、<code>tar -zxvf</code></li></ul><p><strong>我的项目关联</strong><strong>这是真实排障现场</strong>。举两个真实场景：</p><ol><li><strong>服务起不来</strong>：先 <code>netstat -tlnp | grep 端口</code> 看端口是不是<strong>被占了</strong>，再 <code>ps -ef</code> 看有没有<strong>残留进程</strong>。</li><li><strong>磁盘告警</strong>：<code>df -h</code> 看到某个<strong>分区满</strong>，再 <code>du -sh *</code> 逐层找，多半是<strong>日志没清理</strong>。 这些都是<strong>线上真实用过的</strong>手段。</li></ol><p><strong>面试答题话术</strong> 「Linux 我按场景记：排查<strong>端口冲突</strong>用 netstat 加 grep，找日志用 tail -f 和 grep，看资源用 top、free、df。真实例子——服务起不来我第一反应是<strong>查端口是不是被占了</strong>；磁盘告警我一般先 <code>df -h</code> 再 <code>du -sh *</code> <strong>逐层找</strong>，基本都是日志没清。」</p><hr><h2 id="_5-常见安全-xss、csrf、sql-注入-★★★-【简历亮点-高频追问】" tabindex="-1">5. 常见安全：XSS、CSRF、SQL 注入 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_5-常见安全-xss、csrf、sql-注入-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;5. 常见安全：XSS、CSRF、SQL 注入 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>SQL 注入</strong>：用户输入被<strong>当成 SQL 拼进去了</strong>（<code>&#39; OR &#39;1&#39;=&#39;1</code>）。防御核心是<strong>预编译</strong>（<code>#{}</code> / PreparedStatement），让参数<strong>只能当值、不能当语法</strong>。</li><li><strong>XSS</strong>：恶意脚本被注入页面执行，<strong>偷 cookie</strong>。防御：<strong>输出转义</strong>、CSP、HttpOnly、输入过滤。</li><li><strong>CSRF</strong>：诱导你在已登录状态下点恶意链接，<strong>冒充你发请求</strong>。防御：CSRF Token、SameSite Cookie、<strong>校验 Referer</strong>。</li><li>区别一句话：<strong>XSS 是注入脚本利用「用户」，CSRF 是利用「登录态」冒用身份</strong>。</li><li>密码存法：<strong>加盐哈希</strong>（BCrypt），<strong>不能明文、不能裸 MD5</strong>。</li></ul><p><strong>我的项目关联</strong><strong>真实遵守的规范</strong>：所有 SQL 走 MyBatis 的 <code>#{}</code> <strong>预编译</strong>，<strong>禁止用 <code>${}</code> 拼接</strong>（05 笔记专门讲过这个坑）；密码一律 <strong>BCrypt 加盐存储</strong>；对外接口加了 <strong>token 校验和签名</strong>。这些是<strong>线上真实在执行的安全基线</strong>。</p><p><strong>面试答题话术</strong> 「三个我先分清楚：SQL 注入靠<strong>预编译</strong>防，我们 MyBatis 全部用 <code>#{}</code>，禁 <code>${}</code> 拼接；XSS 靠<strong>输出转义</strong>加 HttpOnly；CSRF 靠 token 加 SameSite。密码我们统一 <strong>BCrypt 加盐</strong>，绝不明文也不裸 MD5。这些是项目里<strong>硬性要求</strong>的。」</p><hr><h2 id="_6-越权漏洞-idor-★★★-【简历亮点-高频追问】" tabindex="-1">6. 越权漏洞（IDOR）★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_6-越权漏洞-idor-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;6. 越权漏洞（IDOR）★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li><strong>水平越权</strong>：A 用户改一下 URL 里的 id 就能<strong>看到 B 用户的数据</strong>（同级别）。</li><li><strong>垂直越权</strong>：普通用户<strong>访问了管理员功能</strong>。</li><li>防御关键：<strong>服务端必须做资源归属校验</strong>，前端隐藏按钮<strong>不算安全措施</strong>。</li></ul><p><strong>我的项目关联</strong><strong>真实场景</strong>：充电订单、钱包、发票这些接口，<strong>如果不校验归属</strong>，改个订单号就能<strong>看别人的</strong>。我们的做法是<strong>查询时强制带上当前用户的身份条件</strong>，不是查到再判断。<strong>这是安全底线，不是说说的</strong>。前端虽然也做了隐藏，但<strong>服务端校验才是真的</strong>。</p><p><strong>面试答题话术</strong> 「水平越权就是改 id 看别人数据，垂直越权是<strong>低权限干高权限的事</strong>。防护的核心是服务端做<strong>资源归属校验</strong>——我们的做法是<strong>查询就带当前用户条件</strong>，而不是查出结果再判断，这样<strong>从根上避免越权</strong>。前端隐藏按钮只能算体验优化，不是安全措施。」</p><hr><h2 id="_7-线上排查完整流程-★★★-【简历亮点-高频追问】" tabindex="-1">7. 线上排查完整流程 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_7-线上排查完整流程-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;7. 线上排查完整流程 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 五步：确认现象（<strong>报错、影响范围、能否复现</strong>）→ 看监控（CPU/内存/GC/慢 SQL/错误率）→ 看日志（<strong>错误堆栈</strong>）→ 定位（分头查）→ <strong>修复 + 验证 + 复盘加监控</strong>。 定位的口诀：</p><ul><li>CPU 高 → <code>top</code> + <code>top -Hp</code> + <code>jstack</code></li><li>内存高 / OOM → dump + MAT</li><li>响应慢 → <strong>慢 SQL、下游服务、GC 频率</strong></li><li>报错 → <strong>直接看堆栈</strong></li></ul><p><strong>我的项目关联</strong><strong>这是我最能讲的实战环节</strong>。真实流程：<strong>接口报警</strong> → 看监控确认是<strong>耗时还是错误率</strong> → <strong>抓 traceId 串联日志</strong> → 定位到底是慢 SQL 还是下游。<strong>真实案例</strong>：接口偶发变慢，最后定位是 <strong>Redis 大 key 阻塞</strong>（06 笔记讲过），这整个排查链路我是真的走过。</p><p><strong>面试答题话术</strong> 「排查我按<strong>固定套路</strong>：<strong>先确认现象和影响面</strong>，再看监控判断是<strong>资源问题还是逻辑问题</strong>，然后<strong>抓 traceId 串日志定位</strong>。具体分四种：CPU 高就 top 加 jstack，内存高就 dump 加 MAT，慢就查慢 SQL 和下游，报错直接看堆栈。最后一定要<strong>复盘加监控</strong>——光修完不加告警，下次还会被打个措手不及。」</p><hr><h2 id="_8-线程-dump-分析-★★☆" tabindex="-1">8. 线程 dump 分析 ★★☆ <a class="header-anchor" href="#_8-线程-dump-分析-★★☆" aria-label="Permalink to &quot;8. 线程 dump 分析 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><code>jstack pid &gt; dump.txt</code> 导出<strong>线程快照</strong>，看线程状态：<code>BLOCKED</code>（等锁）、<code>WAITING</code>、<code>RUNNABLE</code>。JDK 自带的<strong>死锁检测</strong>也会直接打印出来。 大量 BLOCKED 说明<strong>锁竞争严重</strong>，要找「<strong>谁持有锁</strong>」。</p><p><strong>我的项目关联</strong><strong>真实用过</strong>：排查 CPU 飙高时配合 <code>top -Hp</code> 把<strong>线程 id 转成十六进制</strong>，再在 jstack 里搜，定位到<strong>具体代码行</strong>。和 02 笔记里讲的是<strong>同一套手法</strong>。</p><p><strong>面试答题话术</strong> 「jstack 导出<strong>线程快照</strong>，重点看 BLOCKED 和<strong>死锁检测</strong>。排查 CPU 高的<strong>标准动作</strong>是 top 找进程、top -Hp 找线程、转成十六进制去 jstack 里搜，<strong>定位到代码行</strong>。这个流程我实际用过。」</p><hr><h2 id="_9-jvm-调优参数-★★☆" tabindex="-1">9. JVM 调优参数 ★★☆ <a class="header-anchor" href="#_9-jvm-调优参数-★★☆" aria-label="Permalink to &quot;9. JVM 调优参数 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 见 02-JVM 篇。核心几个：<code>-Xms</code> / <code>-Xmx</code>（堆）、<code>-XX:+UseG1GC</code>、<code>-XX:MaxGCPauseMillis</code>、<strong>OOM 时 dump</strong>。<strong>容器环境尤其要显式设堆</strong>。</p><p><strong>我的项目关联</strong><strong>真实经验</strong>：<strong>容器部署 + JVM 堆要配套</strong>。我们是显式设 <code>-Xmx</code> 的，不然<strong>容器内存限制和 JVM 认知不一致</strong>，会被 <strong>OOM Killer 杀（exit 137）</strong>。这是<strong>真实踩过的坑</strong>，详见 02 笔记。</p><p><strong>面试答题话术</strong> 「调优参数核心就是<strong>堆大小、G1、GC 暂停目标、OOM dump</strong>。容器里最关键的是显式设 <code>-Xmx</code>，让 JVM <strong>知道容器限制</strong>，防止被 <strong>OOM Killer 干掉</strong>。我们踩过这个坑。」</p><hr><h2 id="_10-日志框架与监控体系-★★☆" tabindex="-1">10. 日志框架与监控体系 ★★☆ <a class="header-anchor" href="#_10-日志框架与监控体系-★★☆" aria-label="Permalink to &quot;10. 日志框架与监控体系 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 日志：<strong>SLF4J 门面 + Logback 实现</strong>，级别 TRACE/DEBUG/INFO/WARN/ERROR，<strong>结构化 JSON + traceId 贯穿</strong>，<strong>不打印敏感信息</strong>。 监控：<strong>指标 Prometheus + Grafana</strong>，<strong>链路 SkyWalking</strong>，<strong>日志 ELK</strong>，阈值告警。</p><p><strong>我的项目关联</strong><strong>真实在用的</strong>：日志打 <strong>traceId 贯穿全链路</strong>，方便排查时串起来；监控有<strong>接口耗时和错误率告警</strong>。<strong>注意点</strong>：手机号、身份证这类敏感字段我们打印时会<strong>脱敏</strong>。</p><p><strong>面试答题话术</strong> 「日志用 SLF4J 加 Logback，关键是<strong>打好 traceId 方便串链路</strong>，<strong>敏感字段必须脱敏</strong>。监控是<strong>指标用 Prometheus 加 Grafana</strong>、链路用 SkyWalking、日志用 ELK。我们用 traceId 排查时特别方便。」</p><hr><h2 id="_11-如果程序员删库跑路了-怎么恢复数据-★★★-场景题" tabindex="-1">11. 如果程序员删库跑路了，怎么恢复数据 ★★★ （场景题） <a class="header-anchor" href="#_11-如果程序员删库跑路了-怎么恢复数据-★★★-场景题" aria-label="Permalink to &quot;11. 如果程序员删库跑路了，怎么恢复数据 ★★★ （场景题）&quot;">​</a></h2><p><strong>通俗理解</strong> 思路三步走：</p><ol><li><strong>止损</strong>：立刻<strong>停写、锁访问</strong>，别再让数据被覆盖。</li><li><strong>恢复</strong>：先恢复最近的<strong>全量备份</strong>，再用 <strong>binlog 增量回放</strong>到删库前一刻（过滤掉 drop/delete）。</li><li><strong>救命</strong>：如果<strong>从库没被同步删掉</strong>（尤其<strong>延迟从库</strong>），直接从从库捞。 <strong>预防比恢复更重要</strong>：定期全量备份 + 开 binlog + <strong>异地备份</strong>、延迟从库、生产库不给开发 drop 权限、删除走<strong>逻辑删除</strong>、定期做<strong>恢复演练</strong>。</li></ol><p><strong>我的项目关联</strong><strong>面试说明</strong>：这是场景题，我们没有真经历过删库（也不希望）。但我们<strong>做了预防措施</strong>：生产库<strong>权限最小化</strong>、删除走<strong>逻辑删除</strong>（<code>is_deleted</code> 标记）、关键表<strong>定期备份</strong>。这里我只能讲方案，不会说成自己救过库。</p><p><strong>面试答题话术</strong> 「这个题我讲思路：<strong>先止损停写</strong>，然后<strong>全量备份恢复加 binlog 回放</strong>到删库前，如果从库还在就直接从从库捞。关键点是要<strong>把 binlog 里删库那一段过滤掉</strong>。但重点其实是预防——<strong>权限最小化、逻辑删除、延迟从库、定期演练</strong>。我们项目做到的是逻辑删除和权限控制，删库恢复本身没真实经历过。」</p><hr><h2 id="_12-删除数据的几种恢复手段-★★☆" tabindex="-1">12. 删除数据的几种恢复手段 ★★☆ <a class="header-anchor" href="#_12-删除数据的几种恢复手段-★★☆" aria-label="Permalink to &quot;12. 删除数据的几种恢复手段 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong></p><ul><li>备份恢复：<strong>全量备份 + binlog 增量回放</strong>。</li><li>延迟从库：<strong>故意慢同步</strong>，主库误删时<strong>从库还有数据</strong>。</li><li>闪回（Flashback）：把 binlog 里的 delete/update <strong>反向解析成 insert/update</strong>，工具如 <strong>binlog2sql、MyFlash</strong>。</li><li>回收站：部分云数据库支持 <strong>drop 先入回收站</strong>。</li></ul><p><strong>我的项目关联</strong><strong>通用坑，了解层面</strong>。我们用<strong>逻辑删除规避了大部分误删风险</strong>，闪回、回收站这些<strong>没实操过</strong>。</p><p><strong>面试答题话术</strong> 「恢复手段有<strong>备份加 binlog 回放</strong>、延迟从库、<strong>binlog 闪回反向解析</strong>、云上的回收站。闪回的原理就是<strong>把 delete 反转成 insert</strong>。这些我了解原理，实际我们<strong>用逻辑删除来规避</strong>。」</p><hr><h2 id="_13-在线调试工具-arthas-★★☆-【简历亮点-高频追问】" tabindex="-1">13. 在线调试工具 Arthas ★★☆ 【简历亮点，高频追问】 <a class="header-anchor" href="#_13-在线调试工具-arthas-★★☆-【简历亮点-高频追问】" aria-label="Permalink to &quot;13. 在线调试工具 Arthas ★★☆ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 阿里开源的 <strong>Java 在线诊断工具</strong>，<strong>不用重启、不用改代码</strong>，<strong>attach 到运行中的 JVM</strong>。最常用的几个命令：</p><ul><li><code>dashboard</code>：总览线程/内存/GC</li><li><code>thread -n 3</code>：最忙的 3 个线程；<code>thread -b</code> 直接找死锁</li><li><code>trace 类 方法</code>：看方法调用耗时，定位性能瓶颈</li><li><code>watch 类 方法 &#39;{params, returnObj, throwExp}&#39;</code>：看入参、返回值、异常</li><li><code>jad 类名</code>：反编译，确认线上跑的到底是哪个版本的代码</li></ul><p><strong>我的项目关联</strong><strong>真实用过，而且是排障利器</strong>。最有用的三个场景：</p><ol><li><strong>怀疑线上代码没生效</strong>：用 <code>jad</code> 反编译<strong>确认版本，比猜靠谱</strong>。</li><li><strong>接口慢</strong>：用 <code>trace</code> 找耗时方法。</li><li><strong>不知道方法入参长啥样</strong>：用 <code>watch</code> 直接看，不用加日志重新发版。 跟 jstack/jmap 的区别：那些是 <strong>JDK 自带、功能单一</strong>；Arthas 更强大，能<strong>交互式在线诊断</strong>。</li></ol><p><strong>面试答题话术</strong> 「Arthas 我最常用三个命令：<code>jad</code> <strong>确认线上代码版本</strong>、<code>trace</code> <strong>定位慢方法</strong>、<code>watch</code> <strong>看方法的入参和异常</strong>。最大价值是<strong>不用重启不用改代码</strong>就能在线诊断。相比 jstack、jmap，它功能更全，是<strong>交互式</strong>的。这个我用得比较熟。」</p><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>Jenkins / CI-CD</strong>：代码提交<strong>自动构建、测试、发布</strong>，知道流水线概念即可。</li><li><strong>Nginx 常用配置</strong>：<strong>反向代理、负载均衡、静态资源、限流</strong>，运维层面了解。</li><li><strong>JProfiler / VisualVM</strong>：本地性能分析工具，Arthas 能覆盖大部分线上需求，知道名字就行。</li><li><strong>SkyWalking vs Zipkin</strong>：都是链路追踪，SkyWalking 对 Java <strong>更友好、无侵入</strong>，知道定位就行。</li></ul>',81)]))}const u=r(g,[["render",e]]);export{h as __pageData,u as default};
